   if(!r||r.peak<BEHIND.minPeak)continue;
   if(r.bytes>BEHIND.maxBytes){warnings.push(`One line of the side caption at ${(b.start/fps).toFixed(1)} s stays in front: its mask is too large.`);continue;}
